import numpy as np

def rref(matrix: list[list[float]]) -> list[list[float]]:
    A = np.array(matrix, dtype=float)
    rows, cols = A.shape
    pivot_row = 0

    for c in range(cols):
        if pivot_row >= rows:
            break
        # Find pivot in column c
        max_r = pivot_row + np.argmax(np.abs(A[pivot_row:, c]))
        if np.isclose(A[max_r, c], 0):
            continue

        # Swap rows
        A[[pivot_row, max_r]] = A[[max_r, pivot_row]]

        # Normalize pivot row
        A[pivot_row] = A[pivot_row] / A[pivot_row, c]

        # Eliminate other rows
        for r in range(rows):
            if r != pivot_row:
                A[r] -= A[r, c] * A[pivot_row]

        pivot_row += 1

    return np.round(A, 4).tolist()

class Solution:
    def myPow(self, x: float, n: int) -> float:
        if n == 0:
            return 1.0
        if n < 0:
            x = 1.0 / x
            n = -n

        res = 1.0
        current_product = x
        while n > 0:
            if n % 2 == 1:
                res *= current_product
            current_product *= current_product
            n //= 2

        return res
